679:     @nogc override number turbulent_viscosity(ref const(FlowState) fs, ref const(FlowGradients) grad, const number ybar, const number dwall) const {
680:         /*
681:         Compute the turbulent viscosity mu_t from the SA transport variable nuhat
682:         See equation (1) from Allmaras (2012)
683:         */
684:         number nuhat = fs.turb[0];
685:         number rho= fs.gas.rho;
686:         number mu = fs.gas.mu;
687:         number chi = rho*nuhat/mu;
688:         number chi_cubed = chi*chi*chi;
689:         number fv1 = chi_cubed/(chi_cubed + cv1_cubed);
690:         number mu_t = rho*nuhat*fv1;
691:         return mu_t;
692:     }
